def transform3(g, clip=False):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    shape=min((v for v in cnt if v!=0),key=lambda v:cnt[v])
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==shape]
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    tm=[(r-min(rs),c-min(cs)) for r,c in cells]
    out=[row[:] for row in g]
    for dr in range(H):
        for dc in range(W):
            ok=True
            for r,c in tm:
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W:
                    if g[rr][cc]!=0: ok=False;break
            if ok:
                for r,c in tm:
                    rr,cc=r+dr,c+dc
                    if 0<=rr<H and 0<=cc<W: out[rr][cc]=shape
    return out
