import numpy as np
def variants(tm):
    a=np.zeros((6,6),int)
    for r,c in tm: a[r][c]=1
    vs=set()
    x=a
    for _ in range(4):
        for y in (x, x[:,::-1]):
            cells=[(r,c) for r,c in zip(*np.nonzero(y))]
            mr=min(r for r,c in cells); mc=min(c for r,c in cells)
            vs.add(tuple(sorted((r-mr,c-mc) for r,c in cells)))
        x=np.rot90(x)
    return vs
